  restoreQuantityDrafts();
  $('companyName').textContent=state.companyName;$('memberName').textContent=state.memberName;$('accountInitial').textContent=(state.companyName.trim()[0]||'B').toUpperCase();$('listCurrency').textContent=state.currency;
