function reviewDate(){return new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Asia/Kuala_Lumpur'}).format(new Date()).replaceAll('/','-')}
function openOrderReview(){
  if(quantityEditsBlocked())return toast('Confirm each edited quantity with Enter and wait for saving to finish.');
  const ordered=state.my.filter(x=>isOrderable(x)&&num(x.orderQtyCtn)>0);
  if(!ordered.length)return toast('Enter a quantity for at least one quoted product.');
  state.pendingOrder=ordered.map(x=>({itemId:x.id,quantityCtn:num(x.orderQtyCtn)}));
  const signature=JSON.stringify(state.pendingOrder);
  if(!state.orderAttempt||state.orderAttempt.signature!==signature)state.orderAttempt={signature,requestId:crypto.randomUUID()};
  $('confirmSubmit').disabled=false;$('confirmSubmit').textContent='Send Request';
  $('reviewItemCount').textContent=ordered.length;$('reviewProducts').textContent=ordered.length;$('reviewCtn').textContent=$('sumCtn').textContent;$('reviewCbm').textContent=$('sumCbm').textContent;$('reviewAmount').textContent=$('sumAmount').textContent;$('reviewCompany').textContent=state.companyName;$('reviewDate').textContent=reviewDate();$('reviewCurrency').textContent=state.currency;$('reviewPriceHeader').textContent=`${state.currency} / CTN`;$('reviewAmountHeader').textContent=`Line Amount / ${state.currency}`;
  $('reviewRows').innerHTML=ordered.map((item,index)=>{const qty=num(item.orderQtyCtn),price=ctnPrice(item),totalCbm=qty*num(item.cbmPerCtn),cbmDisplay=totalCbm===0?'<span class="cbm-zero-pill" title="CBM data is currently unavailable">0.0000</span>':totalCbm.toFixed(4);return `<div class="order-review-line"><div>${index+1}</div><div>${esc(item.barcode)}</div><div title="${esc(item.itemName)}">${esc(item.itemName)}</div><div>${esc(item.packingSize)}</div><div class="review-price">${money(price)}</div><div>${qty.toLocaleString('en-US')}</div><div>${money(qty*price)}</div><div>${cbmDisplay}</div></div>`}).join('');
  $('submitModalBg').classList.add('show');
}
