function downloadOrderExcel(payload){
  try{
    const binary=atob(String(payload?.base64||''));if(!binary)throw new Error('Excel file data is unavailable.');
    const bytes=new Uint8Array(binary.length);for(let index=0;index<binary.length;index+=1)bytes[index]=binary.charCodeAt(index);
    const blob=new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
    let fileName=String(payload?.fileName||'FMCG-Malaysia-Order.xlsx');
    fileName=fileName.replace(/[\\/:*?"<>|]/g,'-');
    const objectUrl=URL.createObjectURL(blob);
    const anchor=document.createElement('a');anchor.href=objectUrl;anchor.download=fileName;anchor.style.display='none';document.body.appendChild(anchor);anchor.click();anchor.remove();
    setTimeout(()=>URL.revokeObjectURL(objectUrl),1500);
    toast('Order Excel download started.');
  }catch(error){toast(error?.message||'Excel download could not be completed.')}
}
window.addEventListener('message',e=>{
  const m=e.data||{};
  if(m.type==='BUYER_ROOM_EXPORT_RESULT'){
    selectionExportBusy=false;
    $('exportToggle').disabled=false;
    if(!m.ok)toast(m.message||'Excel download could not be started.');
    return;
  }
  if(m.type==='BUYER_ROOM_DOWNLOAD_ORDER_EXCEL'){downloadOrderExcel(m);return;}
  if(m.type==='BUYER_ROOM_DATA')applyData(m.data||{});
  if(m.type==='BUYER_ROOM_USER_RESULT'){
    const status=$('accountUserFormStatus');
    if(m.ok){status.className='account-form-status ok';status.textContent=m.action==='primary'?'Primary User updated.':(m.message||'User request submitted.');if(m.action==='request'){$('accountUserForm').reset();setTimeout(()=>{$('accountUserForm').hidden=true;$('accountAddUser').setAttribute('aria-expanded','false')},900)}}
    else{status.className='account-form-status error';status.textContent=m.message||'The user update could not be completed.'}
    $('accountSaveUser').disabled=false;
  }
  if(m.type==='BUYER_ROOM_ACTION_RESULT'){
    if(m.data)applyData(m.data);
    if(m.action==='remove')finishRemove(m);else if(m.action==='recover')finishRestore(m);else if(m.action==='quantity')finishQuantity(m);else if(m.message)toast(m.message);
  }
  if(m.type==='BUYER_ROOM_ORDER_PAGE_RESULT'){
    state.historyLoading=false;
    if(m.ok&&m.customerId!==state.customerId)return;
    if(m.ok){const seen=new Set(state.orders.map(order=>order.orderId));state.orders.push(...(m.orders||[]).filter(order=>!seen.has(order.orderId)));state.ordersNextCursor=m.nextCursor||'';renderOrderTracking()}
    else{renderOrderTracking();toast(m.message||'Order history could not be loaded.')}
  }
  if(m.type==='BUYER_ROOM_ORDER_DETAIL_RESULT'){
    if(m.orderId)state.orderDetailRequests.delete(String(m.orderId));
    if(m.ok&&m.customerId!==state.customerId)return;
    if(m.ok&&m.order?.orderId){state.orderDetailRequests.delete(String(m.order.orderId));const previous=state.orderDetails[m.order.orderId];if(!previous||Number(m.order.revision||0)>=Number(previous.revision||0))state.orderDetails[m.order.orderId]=m.order;renderOrderTracking()}
    else toast(m.message||'Order detail could not be loaded.');
  }
  if(m.type==='BUYER_ROOM_REDUCTION_RESULT'){
    state.reductionSubmitting=false;$('submitReduction').disabled=false;$('submitReduction').textContent='Submit Reduction';
    if(m.ok){$('reductionModalBg').classList.remove('show');state.pendingReduction=null;if(m.order?.orderId){state.orderDetails[m.order.orderId]=m.order;const index=state.orders.findIndex(order=>String(order.orderId)===String(m.order.orderId));if(index>=0)state.orders[index]={...state.orders[index],...m.order,lines:undefined}}renderOrderTracking();toast(m.message||'Reduction request recorded.');post('BUYER_ROOM_REQUEST_DATA',{view:'track'})}
    else toast(m.message||'Reduction request could not be submitted.');
  }
  if(m.type==='BUYER_ROOM_ORDER_REFRESH')requestOrderDetails(true);
  if(m.type==='BUYER_ROOM_ORDER_RESULT'){
    state.orderSubmitting=false;$('confirmSubmit').disabled=false;$('confirmSubmit').textContent='Send Request';
    if(m.ok){
      state.orderAttempt=null;for(const line of state.pendingOrder||[])state.quantityDrafts.delete(String(line.itemId));state.pendingOrder=null;addOrderNotification(m.orderId);
      toast('Order received. View its progress in Track Orders.');
    }else{
      $('submitModalBg').classList.add('show');
      toast(m.message||'Order could not be confirmed.');
    }
  }
});
